import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"SPEC: Fix Model-Schema Mismatches in Backend","description":"","frontmatter":{},"headers":[],"relativePath":"internal/SPEC-model-schema-fixes.md","filePath":"internal/SPEC-model-schema-fixes.md","lastUpdated":1777882948000}'),o={name:"internal/SPEC-model-schema-fixes.md"};function d(c,e,r,n,l,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="spec-fix-model-schema-mismatches-in-backend" tabindex="-1">SPEC: Fix Model-Schema Mismatches in Backend <a class="header-anchor" href="#spec-fix-model-schema-mismatches-in-backend" aria-label="Permalink to &quot;SPEC: Fix Model-Schema Mismatches in Backend&quot;">​</a></h1><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Three independent model-schema mismatches in <code>backend/src/models/</code> cause SQLx runtime failures or latent bugs when queries map result rows to Rust structs.</p><hr><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><h3 id="mismatch-a-teammember-missing-presence" tabindex="-1">Mismatch A: <code>TeamMember</code> missing <code>presence</code> <a class="header-anchor" href="#mismatch-a-teammember-missing-presence" aria-label="Permalink to &quot;Mismatch A: `TeamMember` missing `presence`&quot;">​</a></h3><p><strong>Schema:</strong> <code>team_members.presence VARCHAR(20) NOT NULL DEFAULT &#39;offline&#39;</code> (migration <code>20260402112243</code>)</p><p><strong>Changes:</strong></p><ol><li>Add <code>presence: String</code> to <code>models::team::TeamMember</code>.</li><li>Update <code>api/v4/teams/mod.rs</code> — <code>map_team_member()</code> to read <code>member.presence</code> instead of hard-coding <code>None</code>.</li><li>Update <code>mattermost_compat/mappers.rs</code> — <code>From&lt;TeamMember&gt; for mm::TeamMember</code> to read <code>m.presence</code> instead of hard-coding <code>None</code>.</li><li>Update <code>api/v4/teams/members.rs::get_team_member_me()</code> (line ~196) to use <code>map_team_member(member)</code> instead of manually constructing <code>mm::TeamMember</code> (or at least populate <code>presence</code> from the struct).</li></ol><p><strong>Queries affected (all use <code>SELECT/RETURNING *</code> → <code>TeamMember</code>):</strong></p><ul><li><code>api/teams.rs:207</code> — <code>ensure_team_management_access</code></li><li><code>api/teams.rs:437</code> — <code>join_team</code></li><li><code>api/teams.rs:303</code> — <code>add_team_member</code></li><li><code>api/teams.rs:448</code> — <code>join_team</code> (RETURNING *)</li><li><code>api/admin.rs:1781</code> — <code>add_team_member</code> (RETURNING *)</li><li><code>api/v4/posts/search.rs:56</code> — team membership check</li><li><code>api/v4/teams/members.rs:135</code> — <code>get_team_member</code></li><li><code>api/v4/teams/members.rs:188</code> — <code>get_team_member_me</code></li><li><code>api/v4/teams/members.rs:279</code> — <code>update_team_member_scheme_roles</code></li></ul><h3 id="mismatch-b-post-missing-has-reactions" tabindex="-1">Mismatch B: <code>Post</code> missing <code>has_reactions</code> <a class="header-anchor" href="#mismatch-b-post-missing-has-reactions" aria-label="Permalink to &quot;Mismatch B: `Post` missing `has_reactions`&quot;">​</a></h3><p><strong>Schema:</strong> <code>posts.has_reactions BOOLEAN DEFAULT FALSE</code> (migration <code>20260222000002</code>)</p><p><strong>Changes:</strong></p><ol><li>Add <code>#[sqlx(default)] has_reactions: bool</code> to <code>models::post::Post</code>.</li><li>No query currently selects <code>has_reactions</code> mapped to <code>Post</code>, so this is a defensive alignment.</li></ol><h3 id="mismatch-c-models-post-reaction-is-wrong-for-the-reactions-table" tabindex="-1">Mismatch C: <code>models::post::Reaction</code> is wrong for the <code>reactions</code> table <a class="header-anchor" href="#mismatch-c-models-post-reaction-is-wrong-for-the-reactions-table" aria-label="Permalink to &quot;Mismatch C: `models::post::Reaction` is wrong for the `reactions` table&quot;">​</a></h3><p><strong>Correct schema:</strong> <code>reactions(id UUID, post_id UUID, user_id UUID, emoji_name VARCHAR(64), create_at BIGINT)</code></p><p><strong>Wrong struct:</strong> <code>models::post::Reaction</code> — missing <code>id</code>, field named <code>created_at</code> with type <code>DateTime&lt;Utc&gt;</code> instead of <code>create_at: i64</code>.</p><p><strong>Changes:</strong></p><ol><li><strong>Remove</strong> <code>Reaction</code> from <code>models::post.rs</code>.</li><li><strong>Use</strong> <code>models::reaction::Reaction</code> (correct struct in <code>models/reaction.rs</code>) in all call sites.</li><li><strong>Fix SQL column references</strong> from <code>created_at</code> to <code>create_at</code>: <ul><li><code>api/v4/posts/reactions.rs:318</code> — <code>get_reactions</code> query</li><li><code>api/v4/posts/reactions.rs:175</code> — <code>reactions_for_posts</code> query</li><li><code>api/posts.rs:807</code> — <code>populate_reactions</code> query (<code>ORDER BY create_at</code>)</li></ul></li><li><strong>Fix timestamp arithmetic</strong> in <code>api/v4/posts/reactions.rs</code> — replace <code>reaction.created_at.timestamp_millis()</code> with <code>reaction.create_at</code> (already <code>i64</code>).</li><li><strong>Fix websocket deserialisation</strong> in <code>api/v4/websocket.rs</code> (~lines 1385, 1412) — change <code>models::post::Reaction</code> to <code>models::reaction::Reaction</code>. The inbound JSON payload for websocket events contains <code>create_at: i64</code>, so <code>models::reaction::Reaction</code> deserialises correctly.</li></ol><blockquote><p><strong>Naming collision note:</strong> <code>models::post::ReactionResponse</code> (aggregated emoji→count+users) must remain in <code>post.rs</code>; do NOT add <code>pub use reaction::*</code> to <code>models/mod.rs</code> because <code>reaction.rs</code> also defines a <code>ReactionResponse</code> (Mattermost-compat DTO with different fields). All references to the DB <code>Reaction</code> model must use the explicit path <code>crate::models::reaction::Reaction</code>.</p></blockquote><hr><h2 id="_2-contract-impact" tabindex="-1">2. Contract Impact <a class="header-anchor" href="#_2-contract-impact" aria-label="Permalink to &quot;2. Contract Impact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Impact</th><th>Detail</th></tr></thead><tbody><tr><td><code>mm::TeamMember</code> responses</td><td><strong>Minor additive</strong></td><td><code>presence</code> field will now contain the DB value (<code>&quot;offline&quot;</code>, <code>&quot;online&quot;</code>, etc.) instead of being omitted/ <code>None</code>. This is additive and matches Mattermost mobile expectations.</td></tr><tr><td><code>Post</code> (native API)</td><td>None</td><td><code>has_reactions</code> is not yet emitted in any response; this change only prevents future runtime failures.</td></tr><tr><td><code>mm::Reaction</code> responses</td><td>None</td><td>Reaction endpoints already construct <code>mm::Reaction</code> manually; the fix only corrects the internal mapping layer.</td></tr><tr><td>WebSocket <code>reaction_added</code> / <code>reaction_removed</code></td><td><strong>Fix</strong></td><td>Currently the websocket layer deserialises into the wrong struct (<code>created_at: DateTime&lt;Utc&gt;</code>). After the fix it deserialises into the correct struct (<code>create_at: i64</code>) and produces the same <code>mm::Reaction</code> payload.</td></tr><tr><td><code>post.schema.json</code></td><td>None</td><td>Schema already documents <code>has_reactions: boolean</code>; model now aligns.</td></tr></tbody></table><hr><h2 id="_3-risk-assessment" tabindex="-1">3. Risk Assessment <a class="header-anchor" href="#_3-risk-assessment" aria-label="Permalink to &quot;3. Risk Assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mismatch</th><th>Breaking?</th><th>Risk Level</th><th>Test Requirements</th></tr></thead><tbody><tr><td>A — <code>TeamMember.presence</code></td><td>Non-breaking (additive field on internal struct; API response gains real data)</td><td>Low</td><td>Unit test for <code>TeamMember</code> <code>FromRow</code> with <code>presence</code>. Integration tests for <code>GET /api/v4/teams/{id}/members/{user_id}</code> and <code>GET /api/v4/users/me/teams/members</code>.</td></tr><tr><td>B — <code>Post.has_reactions</code></td><td>Non-breaking (defensive, unused in queries today)</td><td>Very Low</td><td>Compile-time check is sufficient; no runtime path exercises this yet.</td></tr><tr><td>C — <code>Reaction</code> model swap</td><td>Potentially breaking if any caller relied on <code>models::post::Reaction</code> shape</td><td>Medium</td><td>Unit test for <code>models::reaction::Reaction</code> <code>FromRow</code> against <code>reactions</code> table. Integration tests for:<br>• <code>POST /api/v4/posts/{id}/reactions</code><br>• <code>DELETE /api/v4/posts/{id}/reactions/{emoji_name}</code><br>• <code>GET /api/v4/posts/{id}/reactions</code><br>• WebSocket broadcast of <code>reaction_added</code> / <code>reaction_removed</code></td></tr></tbody></table><p><strong>Additional latent bugs fixed as part of C:</strong></p><ul><li><code>api/v4/posts/reactions.rs</code> queries selecting <code>r.created_at</code> (column does not exist → SQLx runtime error).</li><li><code>api/posts.rs:807</code> query ordering by <code>created_at</code> (column does not exist → SQLx runtime error).</li><li><code>api/posts.rs:806</code> query mapping <code>SELECT * FROM reactions</code> to <code>Vec&lt;Reaction&gt;</code> where <code>Reaction</code> resolved to <code>models::post::Reaction</code> (wrong shape → SQLx runtime error).</li></ul><p>These latent bugs suggest the reaction code paths are either untested or the errors are silently swallowed. After the fix, the paths will actually execute.</p><hr><h2 id="_4-verification-criteria" tabindex="-1">4. Verification Criteria <a class="header-anchor" href="#_4-verification-criteria" aria-label="Permalink to &quot;4. Verification Criteria&quot;">​</a></h2><h3 id="compilation" tabindex="-1">Compilation <a class="header-anchor" href="#compilation" aria-label="Permalink to &quot;Compilation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-targets</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> warnings</span></span></code></pre></div><p>Must pass clean.</p><h3 id="integration-tests" tabindex="-1">Integration Tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to &quot;Integration Tests&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-fail-fast</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nocapture</span></span></code></pre></div><p>All existing tests must pass; no new SQLx runtime errors may appear.</p><h3 id="manual-smoke-checks" tabindex="-1">Manual / Smoke Checks <a class="header-anchor" href="#manual-smoke-checks" aria-label="Permalink to &quot;Manual / Smoke Checks&quot;">​</a></h3><ol><li><p><strong>Team member presence:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v4/teams/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TEAM_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/members/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.presence&#39;</span></span></code></pre></div><p>Should return <code>&quot;offline&quot;</code> (or actual presence) instead of <code>null</code>.</p></li><li><p><strong>Reactions round-trip:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add reaction</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;user_id&quot;:&quot;...&quot;,&quot;post_id&quot;:&quot;...&quot;,&quot;emoji_name&quot;:&quot;+1&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v4/posts/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$POST_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/reactions&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List reactions</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v4/posts/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$POST_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/reactions&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[0].create_at&#39;</span></span></code></pre></div><p>Should return a valid millisecond timestamp integer, not a 500 error.</p></li><li><p><strong>WebSocket reaction events:</strong> Connect via WebSocket, add a reaction, verify <code>reaction_added</code> event is broadcast with <code>create_at</code> as integer.</p></li></ol><hr><h2 id="_5-rollback-plan" tabindex="-1">5. Rollback Plan <a class="header-anchor" href="#_5-rollback-plan" aria-label="Permalink to &quot;5. Rollback Plan&quot;">​</a></h2><ol><li><p><strong>Database:</strong> No migrations required; all schema changes are already applied. Rolling back code only affects model-to-row mapping, not the database.</p></li><li><p><strong>Code revert:</strong> The changes are confined to:</p><ul><li><code>backend/src/models/team.rs</code></li><li><code>backend/src/models/post.rs</code></li><li><code>backend/src/models/mod.rs</code> (if <code>pub use reaction::*</code> is added — <strong>do not add it</strong>)</li><li><code>backend/src/api/v4/teams/mod.rs</code></li><li><code>backend/src/mattermost_compat/mappers.rs</code></li><li><code>backend/src/api/v4/teams/members.rs</code></li><li><code>backend/src/api/v4/posts/reactions.rs</code></li><li><code>backend/src/api/posts.rs</code></li><li><code>backend/src/api/v4/websocket.rs</code></li></ul><p>A single <code>git revert</code> of the implementation commit restores the previous (broken) state.</p></li><li><p><strong>Operational:</strong> If a runtime SQLx error surfaces in production after deploy, the query-level failure will return 500. Monitor error rates on:</p><ul><li><code>POST /api/v4/posts/*/reactions</code></li><li><code>DELETE /api/v4/posts/*/reactions/*</code></li><li><code>GET /api/v4/teams/*/members/*</code> Roll back immediately if error rate exceeds baseline.</li></ul></li></ol><hr><h2 id="appendix-files-to-modify" tabindex="-1">Appendix: Files to Modify <a class="header-anchor" href="#appendix-files-to-modify" aria-label="Permalink to &quot;Appendix: Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Lines of Interest</th><th>Change</th></tr></thead><tbody><tr><td><code>backend/src/models/team.rs</code></td><td>31-37</td><td>Add <code>presence: String</code> to <code>TeamMember</code></td></tr><tr><td><code>backend/src/models/post.rs</code></td><td>30-36</td><td>Remove <code>Reaction</code> struct; keep <code>ReactionResponse</code></td></tr><tr><td><code>backend/src/models/post.rs</code></td><td>9-28</td><td>Add <code>#[sqlx(default)] has_reactions: bool</code> to <code>Post</code></td></tr><tr><td><code>backend/src/api/v4/teams/mod.rs</code></td><td>98-111</td><td><code>map_team_member</code> — use <code>member.presence</code></td></tr><tr><td><code>backend/src/api/v4/teams/members.rs</code></td><td>196-204</td><td><code>get_team_member_me</code> — use <code>map_team_member</code> or populate <code>presence</code></td></tr><tr><td><code>backend/src/mattermost_compat/mappers.rs</code></td><td>274-287</td><td><code>From&lt;TeamMember&gt;</code> — use <code>m.presence</code></td></tr><tr><td><code>backend/src/api/v4/posts/reactions.rs</code></td><td>94-106</td><td>Use <code>crate::models::reaction::Reaction</code>; fix timestamp</td></tr><tr><td><code>backend/src/api/v4/posts/reactions.rs</code></td><td>138-147</td><td>Use <code>reaction.create_at</code> instead of <code>.timestamp_millis()</code></td></tr><tr><td><code>backend/src/api/v4/posts/reactions.rs</code></td><td>173-183</td><td>Fix <code>r.created_at</code> → <code>r.create_at</code> in query</td></tr><tr><td><code>backend/src/api/v4/posts/reactions.rs</code></td><td>255-262</td><td>Use <code>crate::models::reaction::Reaction</code></td></tr><tr><td><code>backend/src/api/v4/posts/reactions.rs</code></td><td>279-288</td><td>Fix <code>r.created_at</code> → <code>r.create_at</code> in query and timestamp handling</td></tr><tr><td><code>backend/src/api/posts.rs</code></td><td>806-810</td><td>Use <code>crate::models::reaction::Reaction</code>; fix <code>ORDER BY create_at</code></td></tr><tr><td><code>backend/src/api/v4/websocket.rs</code></td><td>1383-1408</td><td>Use <code>crate::models::reaction::Reaction</code>; fix <code>create_at</code> handling</td></tr><tr><td><code>backend/src/api/v4/websocket.rs</code></td><td>1410-1425</td><td>Use <code>crate::models::reaction::Reaction</code>; fix <code>create_at</code> handling</td></tr></tbody></table>',46)])])}const k=t(o,[["render",d]]);export{m as __pageData,k as default};
